/* 1. minimizers vs brute force */
check('minimizer extraction matches brute force (all windows)', () => {
  const bases = 'ACGT';
  let seed = 12345;
  const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
  for (let t = 0; t < 200; t++) {
