    const m = cans.length;
    for (let i = 0; i < m; i++) {
      const lo = Math.max(0, Math.min(i - w + 1, m - 1));
      const hi = i;
      let bestIdx = lo;
      for (let j = lo; j <= hi; j++) if (cans[j] < cans[bestIdx]) bestIdx = j;
      const expect = i >= w - 1 ? cans[bestIdx] : cans[i];
      assert.strictEqual(mins[i], expect, `i=${i} s=${s} k=${k} w=${w}`);
